#!/usr/bin/env python3
"""Tests of the entry points generated by `frontx_entry` / `frontx_implements` (`Riscv/Frontx/Machine.lean`; words
from `Testing/asm/emit_frontx.lean` in `Testing/asm/frontx-words/`, first line = slots) on QEMU and on the Sail C
emulator, in the `Implements1` calling convention (`Spec/Implements1.lean`): a0 = input, a1 = length, a2 = work
base (8-aligned), a3 = output, sp = work end.

check N [function]: the first N cases of `frontx-words/<function>.cases` (inputs and the result bytes computed by
Lean, `#eval` of the function in `emit_frontx.lean`; lengths up to 3000), and for the functions in `FUNCS` also the
Python reference.  Each case gets its own input / output (exactly the result's bytes) / work block
(`8 * (slots + 1) + 7` bytes = `space n`, at an 8-aligned base), each followed by 16 guard bytes; the driver sets gp
to a magic value before the call and stores gp, sp, a1 after it.  Checked on QEMU and Sail: output = Lean's result,
input, guards unchanged, gp and sp restored, a1 = result length for list results (`retLen`), and (Sail) every data
write lands in the result bytes or in the work block.
usage: frontx_test.py check N [function]"""
import os, random, re, subprocess, sys, zlib
D = os.path.dirname(os.path.abspath(__file__)); W = os.environ.get("CTEST", os.path.join(D, "ctest")); os.makedirs(W, exist_ok=True)
SAIL = "/home/user/deps/sailsim/sail-riscv-Linux-x86_64/bin/sail_riscv_sim"
p = lambda f: os.path.join(W, f)
sh = lambda c: subprocess.run(c, shell=True, check=True)
def b64digit(c):
    if 65 <= c <= 90: return c - 65
    if 97 <= c <= 122: return c - 71
    if 48 <= c <= 57: return c + 4
    return 62 if c == 43 else 63 if c == 47 else 64
at = lambda xs, i: xs[i] if i < len(xs) else 0
# name -> (result bytes, reference)
FUNCS = {
    "crcraw": (4, lambda xs: zlib.crc32(bytes(xs)) ^ 0xFFFFFFFF),
    "b64all": (4, lambda xs: sum(b64digit(c) for c in xs) % 2 ** 32),
    "findnl": (8, lambda xs: next((k for k, c in enumerate(xs) if c == 10), len(xs))),
    "be32at0": (8, lambda xs: at(xs, 0) << 24 | at(xs, 1) << 16 | at(xs, 2) << 8 | at(xs, 3)),
    "tailsum": (8, lambda xs: sum(xs)),
    "nontailsum": (8, lambda xs: sum(xs)),
    "taillength": (8, lambda xs: len(xs)),
    "booklength": (8, lambda xs: len(xs)),
}
# functions returning a list: the length is returned in a1
opt = lambda o: bytes([0, 0]) if o is None else bytes([1, o])
REFS = {"take5": lambda x: bytes(x[:5]), "drop5": lambda x: bytes(x[5:]), "matchdrop3": lambda x: bytes(x[3:]),
        "filterall": lambda x: bytes(c for c in x if c > 3), "inceach": lambda x: bytes((c + 1) & 255 for c in x),
        "twice": lambda x: bytes(x + x), "headof": lambda x: opt(x[0] if x else None),
        "finalof": lambda x: opt(x[-1] if x else None), "findfirstgt3": lambda x: opt(next((c for c in x if c > 3), None))}
LISTS = {"take5", "drop5", "matchdrop3", "filterall", "inceach", "twice"}
FN = sys.argv[3] if len(sys.argv) > 3 else "crcraw"
unhex = lambda h: [] if h == "-" else list(bytes.fromhex(h))
CASES = [tuple(map(unhex, l.split())) for l in open(os.path.join(os.environ.get("CASESDIR", os.path.join(D, "frontx-words")), FN + ".cases")) if l.strip()]
lines = [l for l in open(os.path.join(D, "frontx-words", FN + ".words")) if l.strip()]
words = [int(l, 16) for l in lines[1:]]
G, WK, E = 16, 8 * (int(lines[0]) + 1) + 7, 72
MAGIC = 0x0123456789ABCDEF
LD = "ENTRY(_start)\nSECTIONS { . = 0x80000000; .text : { *(.text.start) *(.text) }\n . = 0x80100000; .tohost : { *(.tohost) }\n . = 0x80200000; .data : { *(.data) } }\n"
TAIL = """.section .tohost,"aw"
.globl tohost
.globl fromhost
.align 6
tohost: .dword 0
fromhost: .dword 0
"""
DRIVER = """.section .text.start
.globl _start
_start: lla s0, tab
  li s2, %d
1: ld a0, 0(s0)
  ld a1, 8(s0)
  ld a2, 16(s0)
  ld a3, 24(s0)
  ld sp, 32(s0)
  ld gp, 40(s0)
  jal ra, func
  sd gp, 48(s0)
  sd sp, 56(s0)
  sd a1, 64(s0)
  addi s0, s0, %d
  addi s2, s2, -1
  bnez s2, 1b
  lla t0, tohost
  li t1, 1
  sd t1, 0(t0)
halt: j halt
func:
%s""" + TAIL

def build(cases, func):
    """per case: [in | G][out R | G][pad to 8][work WK | G], R = the length of Lean's result"""
    data, tab, off, lay = [], [], 0, []
    for xs, ys in cases:
        R = len(ys)
        L = len(xs); i0 = off; o0 = i0 + L + G; w0 = (o0 + R + G + 7) // 8 * 8; off = w0 + WK + G
        lay.append((i0, o0, w0))
        tab.append(f"  .quad base+{i0}, {L}, base+{w0}, base+{o0}, base+{w0 + WK}, {MAGIC}, 0, 0, 0")
        data.append(bytes(xs) + b"\xAA" * G + b"\x55" * R + b"\xAA" * G + b"\x00" * (w0 - (o0 + R + G))
                    + b"\x77" * WK + b"\xAA" * G)
    open(p("crc.bin"), "wb").write(b"".join(data))
    src = DRIVER % (len(cases), E, func) + f'.data\n.align 4\nbase:\n.incbin "{p("crc.bin")}"\n.align 3\ntab:\n' + "\n".join(tab) + "\n"
    open(p("crc.S"), "w").write(src); open(p("m.ld"), "w").write(LD)
    sh(f"riscv64-linux-gnu-gcc -march=rv64i_zicsr -mabi=lp64 -nostdlib -static -Wl,-T,{p('m.ld')} -Wl,--no-relax "
       f"-Wl,--build-id=none {p('crc.S')} -o {p('crc.elf')}")
    syms = subprocess.check_output(f"riscv64-linux-gnu-nm {p('crc.elf')}", shell=True, text=True)
    sym = lambda s: int(re.search(rf"(\w+) \w {s}\n", syms).group(1), 16)
    return lay, sym("halt"), sym("base"), sym("tab"), off

def qemu(halt, a, n):
    q = subprocess.Popen(f"qemu-system-riscv64 -machine virt -m 1G -bios {p('crc.elf')} -display none -serial none "
                         f"-monitor stdio", shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=0)
    def hmp(c):
        q.stdin.write(c + "\n"); buf = ""
        while not buf.endswith("(qemu) ") or c not in buf: buf += q.stdout.read(1)
        return buf
    hmp("info version")
    while "pc       %016x" % halt not in hmp("info registers"): pass
    hmp(f'pmemsave {a:#x} {n} "{p("crc.q.bin")}"'); q.stdin.write("quit\n"); q.wait()
    return open(p("crc.q.bin"), "rb").read()

def check(N):
    cases = CASES[:N]
    func = "".join(f"  .word 0x{w:08x}\n" for w in words)
    lay, halt, base, tab, size = build(cases, func)
    qmem = qemu(halt, base, tab + E * len(cases) - base)
    init = bytearray(open(p("crc.bin"), "rb").read()) + bytearray(qmem[size:])
    # everything outside tab, result bytes and work blocks must equal the initial image (QEMU)
    keep = bytearray(init)
    for (i0, o0, w0), (xs, ys) in zip(lay, cases):
        keep[o0:o0 + len(ys)] = qmem[o0:o0 + len(ys)]; keep[w0:w0 + WK] = qmem[w0:w0 + WK]
    keep[tab - base:] = qmem[tab - base:]
    assert bytes(keep) == bytes(qmem[:len(keep)]), "QEMU: memory changed outside output/work"
    mems = [("qemu", qmem)]
    if not os.environ.get("NOSAIL"):
        r = subprocess.run(f"{SAIL} --inst-limit 2000000000 --trace-mem --trace-output {p('sail.log')} {p('crc.elf')}",
                           shell=True, capture_output=True, text=True)
        assert "SUCCESS" in r.stdout + r.stderr, (r.stdout + r.stderr)[-500:]
        ok = bytearray(len(init))
        for i in range(tab - base, len(init)): ok[i] = 1
        for (i0, o0, w0), (xs, ys) in zip(lay, cases):
            for i in range(o0, o0 + len(ys)): ok[i] = 1
            for i in range(w0, w0 + WK): ok[i] = 1
        smem = bytearray(init)
        for l in open(p("sail.log")):
            m = re.match(r"mem\[(?:W,)?0x([0-9A-F]+)\] <- 0x([0-9A-F]+)", l)
            if not m: continue
            a, v = int(m.group(1), 16), m.group(2)
            if a < base: continue
            nb = len(v) // 2
            for j in range(nb):
                assert ok[a + j - base], f"unexpected Sail write {l.strip()}"
                smem[a + j - base] = int(v[2 * (nb - 1 - j):2 * (nb - j)], 16)
        mems.append(("sail", smem))
    for nm, mem in mems:
        for c, ((i0, o0, w0), (xs, ys)) in enumerate(zip(lay, cases)):
            L = len(xs); R = len(ys)
            assert list(mem[i0:i0 + L + G]) == xs + [0xAA] * G, (nm, "input", L)
            want = bytes(ys)
            if FN in FUNCS:
                assert want == FUNCS[FN][1](xs).to_bytes(FUNCS[FN][0], "little"), ("Lean != Python reference", FN, L)
            if FN in REFS: assert want == REFS[FN](xs), ("Lean != Python reference", FN, len(xs), want.hex()[:40])
            assert bytes(mem[o0:o0 + R]) == want, (nm, FN, L, bytes(mem[o0:o0 + R]).hex(), want.hex())
            assert list(mem[o0 + R:o0 + R + G]) == [0xAA] * G, (nm, "output guard", L)
            assert list(mem[w0 + WK:w0 + WK + G]) == [0xAA] * G, (nm, "work guard", L)
            e = tab - base + E * c
            gp, spo, a1 = (int.from_bytes(mem[e + o:e + o + 8], "little") for o in (48, 56, 64))
            assert gp == MAGIC and spo == base + w0 + WK, (nm, "gp/sp", hex(gp), spo)
            if FN in LISTS: assert a1 == R, (nm, "a1 (length)", a1, R)
    print(f"{FN}: {len(cases)} cases ok (QEMU == Sail == Lean; input lengths up to {max(len(x) for x, _ in cases)}; "
          f"{len(words)} words, work {WK} bytes)")

if sys.argv[1] == "check": check(int(sys.argv[2]))
